 bool bindVerifiedFirmware(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_||active()||!image||size!=49728||!d.hasImmutableCapacity(10))return false;for(auto r:ranges_)for(uint32_t a=r.begin;a<r.end;++a)if(d.readResource(a)!=image[a]||d.readResource(0x400000+a)!=image[a])return false;for(auto r:ranges_)if(!d.protectImmutableVerified(r.begin,r.end,image+r.begin)||!d.protectImmutableVerified(0x400000+r.begin,0x400000+r.end,image+r.begin))return false;bound_=&d;return true;}
 bool boundTo(const ControllerDeviceState&d)const{return bound_==&d;}bool start(Kind kind){if(!bound_||active())return false;task_.emplace(kind);return true;}bool active()const{return bool(task_);}void reset(){if(effects_){effects_->reset();if(effectsDsp_&&effectsDsp_->active())effectsDsp_->reset();effects_=nullptr;effectsDsp_=nullptr;}if(parameters_){parameters_->reset();if(parameterDsp_&&parameterDsp_->active())parameterDsp_->reset();parameters_=nullptr;parameterDsp_=nullptr;}if(pitch_){pitch_->reset();if(pitchDsp_&&pitchDsp_->active())pitchDsp_->reset();pitch_=nullptr;pitchDsp_=nullptr;}if(modulation_){modulation_->reset();if(modulationDsp_&&modulationDsp_->active())modulationDsp_->reset();modulation_=nullptr;modulationDsp_=nullptr;}task_.reset();voice_.reset();copy_.reset();select_.reset();address_.reset();if(dsp_&&dsp_->active())dsp_->reset();dsp_=nullptr;ownsDsp_=false;}Request request()const{return task_&&!voice_&&!copy_&&!select_&&!address_&&!modulation_&&!pitch_&&!parameters_&&!effects_?Request{task_->child(),task_->part(),task_->voice(),task_->patch()}:Request{};}bool completeChild(Child child,uint32_t voice=0){return task_&&!voice_&&!copy_&&!select_&&!address_&&!modulation_&&!pitch_&&!parameters_&&!effects_&&child!=Child::None&&task_->child()==child&&task_->resumeChild(voice);}
